create or replace function allocate_spin(p_campaign text,p_name text,p_phone text,p_request_id uuid) returns table(spin_id uuid,prize_code text,prize_name text,sector int,turn_left int) language plpgsql security definer set search_path=public as $$ declare c campaigns; part participants; u prize_units; s spins; begin select * into c from campaigns where code=p_campaign and status='ACTIVE' and(starts_at is null or starts_at<=now())and(ends_at is null or ends_at>=now());if not found then raise exception 'CAMPAIGN_INACTIVE';end if;select sp.* into s from spins sp where sp.request_id=p_request_id;if found then return query select s.id,p.code,p.name,p.wheel_index,0 from prizes p where p.id=s.prize_id;return;end if;insert into participants(campaign_id,name,phone,phone_normalized)values(c.id,trim(p_name),p_phone,regexp_replace(p_phone,'\D','','g'))on conflict(campaign_id,phone_normalized)do update set name=excluded.name returning * into part;if exists(select 1 from spins where campaign_id=c.id and participant_id=part.id)then raise exception 'ALREADY_SPUN';end if;select pu.* into u from prize_units pu where pu.campaign_id=c.id and pu.status='AVAILABLE' order by random() for update skip locked limit 1;if not found then raise exception 'CAMPAIGN_SOLD_OUT';end if;insert into spins(campaign_id,participant_id,prize_id,prize_unit_id,request_id)values(c.id,part.id,u.prize_id,u.id,p_request_id)returning * into s;update prize_units set status='AWARDED',awarded_at=now(),participant_id=part.id,spin_id=s.id where id=u.id;return query select s.id,p.code,p.name,p.wheel_index,0 from prizes p where p.id=u.prize_id;end$$;revoke all on function allocate_spin(text,text,text,uuid) from public,anon,authenticated;
